const catalog=['Mathematics','Physics','Chemistry','Biology','English','Tamil','Hindi','Computer science','Coding','Artificial intelligence','Data analysis','Communication','Public speaking','Leadership','Classroom management','Lesson planning','Assessment design','CBSE teaching','Cambridge teaching','Inclusive education','Early childhood education','Phonics','Art','Music','Dance','Sports coaching','NEET preparation','JEE preparation','Career guidance','Teacher development','Digital literacy','Entrepreneurship'];
function record(){const r=state.role;if(!registration.records[r])registration.records[r]={fields:{},skills:[],evidence:[],links:[],complete:false};return registration.records[r]}
function fieldHTML(f){let val=record().fields[f.key]??'',attrs=`name="${f.key}" ${f.required?'required':''}`;let control=f.type==='select'?`<select ${attrs}><option value="">Choose an option</option>${f.options.map(x=>`<option ${x===val?'selected':''}>${esc(x)}</option>`).join('')}</select>`:f.type==='textarea'?`<textarea ${attrs} maxlength="2000">${esc(val)}</textarea>`:`<input ${attrs} type="${f.type}" ${f.type==='number'?'min="0" step="1"':''} maxlength="300" value="${esc(val)}">`;return `<label class="${f.type==='textarea'?'full':''}">${f.label}${f.required?' *':' (optional)'}${control}</label>`}
function stepFields(n){return n===0?common:n===1?questions[state.role].background:n===3?questions[state.role].preferences:[]}
function saveFields(){const form=$('#registration-form');if(!form)return;new FormData(form).forEach((v,k)=>{record().fields[k]=v});if(registration.step===5){['marketingEmail','marketingPhone','marketingWhatsapp','accuracy','guardian','contactShare'].forEach(k=>record().fields[k]=!!form.elements[k]?.checked)}record().complete=false}
function currentValid(){const form=$('#registration-form');if(form&&!form.reportValidity())return false;if(registration.step===2&&!record().skills.length){toast('Add at least one skill to continue.');return false}return true}
function advance(){if(!currentValid())return;saveFields();registration.step++;profile();window.scrollTo(0,0)}
function backStep(){saveFields();registration.step=Math.max(0,registration.step-1);profile()}
function jumpStep(n){saveFields();registration.step=n;profile()}
function skillLabel(){return {learner:'Skills I want to learn or already have',teacher:'Skills I can teach or use professionally',institution:'Skills we need or develop in our students',training:'Skills our programmes develop'}[state.role]}
function skillsHTML(){const r=record();return `<p class="muted">${skillLabel()}. Add all relevant skills. Proficiency is self-declared; evidence can be linked in the next steps.</p><div class="skill-builder"><label>Choose a skill<select id="skill-pick"><option value="">Choose from the list</option>${catalog.map(s=>`<option>${s}</option>`).join('')}</select></label><label>Or add a skill not listed<input id="custom-skill" maxlength="100" placeholder="e.g. Abacus, robotics, pottery"></label><label>Skill purpose<select id="skill-purpose">${(state.role==='learner'?['Want to learn','Already have']:state.role==='teacher'?['Can teach','Professional strength','Want to learn']:state.role==='institution'?['Hiring requirement','Institutional offering','Staff development']:['Training offered','Trainer strength','Want to develop']).map(s=>`<option>${s}</option>`).join('')}</select></label><label>Proficiency / target level<select id="skill-level">${['Beginner','Intermediate','Advanced','Expert','Not assessed'].map(s=>`<option>${s}</option>`).join('')}</select></label><label>Experience in this skill (years, optional)<input id="skill-years" type="number" min="0" max="80" step="0.5"></label><label>Priority<select id="skill-priority"><option>Primary</option><option>Additional</option></select></label></div><button class="btn light" type="button" onclick="addSkill()">+ Add skill</button><div class="skill-list">${r.skills.map((s,i)=>`<div class="skill-row"><div><strong>${esc(s.name)}</strong> ${s.custom?'<span class="badge">Custom skill</span>':''}<p>${esc(s.purpose)} · ${s.level} · ${s.priority}${s.years!==''?' · '+s.years+' years':''}</p></div><button class="btn outline" type="button" onclick="removeSkill(${i})" aria-label="Remove ${esc(s.name)}">Remove</button></div>`).join('')||'<p class="muted">No skills added yet. Add at least one to continue.</p>'}</div>`}
function addSkill(){const custom=$('#custom-skill').value.trim(),name=custom||$('#skill-pick').value,years=$('#skill-years');if(!name){toast('Choose or type a skill.');return}if(!years.reportValidity())return;const purpose=$('#skill-purpose').value;if(record().skills.some(x=>x.name.toLowerCase()===name.toLowerCase()&&x.purpose===purpose)){toast('This skill and purpose are already added.');return}record().skills.push({name,custom:!!custom,purpose,level:$('#skill-level').value,years:years.value,priority:$('#skill-priority').value});record().complete=false;profile()}
function removeSkill(i){record().skills.splice(i,1);record().complete=false;profile()}
function evidenceHTML(){const r=record();return `<p class="muted">Support your profile with relevant evidence. All evidence is optional and unverified. Files selected here remain in this browser session and are not uploaded yet.</p><div class="notice">Do not upload sensitive documents yet. Files and links disappear on refresh. Video links may be public or unlisted; no verification is claimed.</div><div class="skill-builder"><label>Document type<select id="evidence-kind">${(state.role==='teacher'?['Résumé / CV','Qualification certificate','Skill certificate','Experience letter','Portfolio']:state.role==='learner'?['Learning portfolio','Skill certificate','Other evidence']:['Institution brochure','Affiliation / registration certificate','Trainer résumé','Skill / accreditation certificate','Portfolio']).map(s=>`<option>${s}</option>`).join('')}</select></label><label>Related skill<select id="evidence-skill"><option value="">General profile</option>${r.skills.map(s=>`<option>${esc(s.name)}</option>`).join('')}</select></label><label class="full">Select PDF, DOCX, JPG or PNG (10 MB maximum)<input type="file" id="evidence-file" accept=".pdf,.docx,.jpg,.jpeg,.png"></label></div><button type="button" class="btn light" onclick="attachFile()">+ Attach file</button><div class="skill-list">${r.evidence.map((e,i)=>`<div class="skill-row"><div><strong>${esc(e.name)}</strong><p>${esc(e.kind)} · ${esc(e.skill||'General profile')} · ${Math.ceil(e.size/1024)} KB · Local only</p></div><div class="workspace-links"><a class="btn outline" href="${e.url}" download="${esc(e.name)}">Download</a><button type="button" class="btn outline" onclick="removeEvidence(${i})">Remove</button></div></div>`).join('')}</div><h3>Videos & other evidence links</h3><div class="skill-builder"><label>Link type<select id="link-kind"><option>Teaching / training demo video</option><option>Skill demonstration</option><option>Portfolio website</option><option>Certificate verification page</option><option>Institution tour</option></select></label><label>Related skill<select id="link-skill"><option value="">General profile</option>${r.skills.map(s=>`<option>${esc(s.name)}</option>`).join('')}</select></label><label>Title<input id="link-title" maxlength="150" placeholder="e.g. My science demonstration"></label><label>Video / evidence URL<input id="link-url" type="url" placeholder="https://..."></label></div><button type="button" class="btn light" onclick="addEvidenceLink()">+ Add evidence link</button>${r.links.map((e,i)=>`<div class="skill-row"><div><a href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">${esc(e.title)} ↗</a><p>${esc(e.kind)} · ${esc(e.skill||'General profile')} · Unverified</p></div><button type="button" class="btn outline" onclick="removeLink(${i})">Remove</button></div>`).join('')}`}
function attachFile(){const f=$('#evidence-file').files[0];if(!f){toast('Select a file first.');return}if(f.size>10*1024*1024||! /\.(pdf|docx|jpe?g|png)$/i.test(f.name)){toast('Choose a PDF, DOCX, JPG or PNG up to 10 MB.');return}record().evidence.push({name:f.name,size:f.size,url:URL.createObjectURL(f),kind:$('#evidence-kind').value,skill:$('#evidence-skill').value});record().complete=false;profile()}
function removeEvidence(i){URL.revokeObjectURL(record().evidence[i].url);record().evidence.splice(i,1);profile()}
function addEvidenceLink(){const url=$('#link-url').value.trim(),title=$('#link-title').value.trim();try{const u=new URL(url);if(!['http:','https:'].includes(u.protocol))throw Error();if(!title)throw Error();record().links.push({url:u.href,title,kind:$('#link-kind').value,skill:$('#link-skill').value});record().complete=false;profile()}catch{toast('Add a title and a valid http:// or https:// link.')}}
function removeLink(i){record().links.splice(i,1);profile()}
const checkbox=(key,label,required=false)=>`<label class="check-row"><input type="checkbox" name="${key}" ${record().fields[key]?'checked':''} ${required?'required':''}><span>${label}${required?' *':''}</span></label>`;
function consentHTML(){return `<div class="fields">${[field('source','How did you hear about Talind?','select',['Search engine','Social media','Friend / colleague','School / institution','Event / workshop','Advertisement','Other'],true),field('sourceDetail','Referral / campaign / other source detail'),field('decisionRole','Your role in the decision','select',['Learner / self','Parent / guardian','Decision maker','Recommender','Coordinator','Other'],true),field('contactChannel','Preferred channel for service enquiries','select',['Email','Phone','WhatsApp','No direct contact yet'],true),field('contactTime','Best time to contact'),field('purchaseTimeline','When are you likely to decide?','select',['This week','This month','Within 3 months','Just exploring'],true)].map(fieldHTML).join('')}</div><h3>Profile and enquiry preferences</h3><p class="muted">Contact details, documents and learner information are not public. Your selections are stored only for this browser session until persistent account storage is connected.</p>${checkbox('accuracy','I confirm that the information I provide is accurate and that I have permission to use the evidence.',true)}${state.role==='learner'?checkbox('guardian','I am 18 or older. If this profile is for a child, I am their parent or authorised guardian.',true):''}${checkbox('contactShare','Allow my contact details to be shared with a provider only when I send that provider an enquiry.')}<h3>Optional marketing choices</h3><p class="muted">These are optional, start unchecked and can be changed later. They do not affect access.</p>${checkbox('marketingEmail','Email me relevant Talind offers and programme updates.')}${checkbox('marketingPhone','Contact me by phone about relevant Talind services.')}${checkbox('marketingWhatsapp','Send relevant Talind updates on WhatsApp.')}<p class="bottom-note">Marketing messaging is not yet enabled.</p>`}
function missingFields(){let m=[];[...common,...questions[state.role].background,...questions[state.role].preferences,field('source','How did you hear about Talind?','text',[],true),field('decisionRole','Decision role','text',[],true),field('contactChannel','Preferred contact channel','text',[],true),field('purchaseTimeline','Decision timeline','text',[],true)].filter(f=>f.required).forEach(f=>{if(!String(record().fields[f.key]??'').trim())m.push(f.label)});if(!record().skills.length)m.push('At least one skill');if(!record().fields.accuracy)m.push('Accuracy confirmation');if(state.role==='learner'&&!record().fields.guardian)m.push('Adult / guardian confirmation');return m}
function reviewHTML(){const r=record(),m=missingFields();return `<div class="notice ${m.length?'':'success'}">${m.length?m.length+' required items still need attention.':'Your required profile details are complete.'} Evidence is optional.</div>${[0,1,3].map(n=>`<section class="review-section"><div class="section-top"><h3>${sections[n]}</h3><button type="button" class="btn outline" onclick="jumpStep(${n})">Edit</button></div><dl>${stepFields(n).map(f=>`<div><dt>${f.label}</dt><dd>${esc(r.fields[f.key]||'Not provided')}</dd></div>`).join('')}</dl></section>`).join('')}<section class="review-section"><h3>Skills & evidence</h3><div class="tags">${r.skills.map(s=>`<span>${esc(s.name)} · ${s.level} · ${esc(s.purpose)}</span>`).join('')}</div><p>${r.evidence.length} local document(s) · ${r.links.length} evidence link(s)</p><button class="btn outline" type="button" onclick="jumpStep(2)">Edit skills</button> <button class="btn outline" type="button" onclick="jumpStep(4)">Edit evidence</button></section><section class="review-section"><h3>Contact & marketing preferences</h3><p>Service contact: ${esc(r.fields.contactChannel||'Not set')} · Source: ${esc(r.fields.source||'Not set')}</p><p>Marketing: ${['marketingEmail','marketingPhone','marketingWhatsapp'].filter(k=>r.fields[k]).map(k=>({marketingEmail:'Email',marketingPhone:'Phone',marketingWhatsapp:'WhatsApp'}[k])).join(', ')||'No opt-ins'}</p><button type="button" class="btn outline" onclick="jumpStep(5)">Edit preferences</button></section>${m.length?`<p class="form-error">Missing: ${m.map(esc).join('; ')}</p>`:''}<button type="button" class="btn" onclick="completeProfile()">Complete registration</button><p class="bottom-note">Information is currently retained only for this browser session. Persistent account storage, document upload and subscriptions are not yet connected.</p>`}
function completeProfile(){const m=missingFields();if(m.length){toast('Complete the required items listed in the review.');return}record().complete=true;const f=record().fields;state.profiles[state.role]={name:f.name,title:f.headline||roleNames[state.role],location:f.city,skills:record().skills.map(s=>s.name).join(', '),bio:f.bio||f.goals||''};toast('Registration completed for this session. Your profile is ready to review.');profile()}
// Extend the existing profile route with structured onboarding.
profile=function(){const r=record(),n=registration.step;$('#main').innerHTML=intro('SKILLS-FIRST REGISTRATION',r.complete?'Your profile, ready to connect.':'Tell your complete story.',`${roleNames[state.role]} · Required questions are marked *. Documents and marketing opt-ins are optional.`)+`<div class="notice">Your profile fields are saved to your Talind account when signed in. Selected local files are not uploaded yet.</div><div class="onboard-layout"><div class="step-nav">${sections.map((s,i)=>`<button type="button" class="step-button ${i===n?'active':''}" onclick="jumpStep(${i})"><span>${i+1}</span>${s}</button>`).join('')}<div class="completion">${r.complete?'✓ Registration complete':'Profile in progress'}</div></div><section class="panel onboarding-panel"><span class="eyebrow">STEP ${n+1} OF ${sections.length}</span><h2>${sections[n]}</h2><form id="registration-form">${[0,1,3].includes(n)?`<div class="fields">${stepFields(n).map(fieldHTML).join('')}</div>`:n===2?skillsHTML():n===4?evidenceHTML():n===5?consentHTML():reviewHTML()}<div class="step-actions">${n>0?'<button class="btn outline" type="button" onclick="backStep()">Back</button>':''}${n<6?'<button class="btn" type="submit">Save & continue →</button>':''}<button class="btn light" type="button" onclick="saveFields();toast('Draft saved locally. Sign in to keep it with your Talind account.')">Save draft</button></div></form></section></div>`;$('#registration-form').onsubmit=e=>{e.preventDefault();advance()}}
function authScreen(kind='signup'){modal(`<span class="eyebrow">${kind==='signup'?'SIGN UP':'LOG IN'}</span><h2>${kind==='signup'?'Start your Talind profile.':'Welcome back to Talind.'}</h2><div class="notice">Account sign-in is not yet connected.</div><form id="auth-form"><div class="fields"><label class="full">Email<input name="email" type="email" required placeholder="you@example.com"></label><label class="full">Profile category<select name="role">${Object.entries(roleNames).map(([k,v])=>`<option value="${k}" ${k===state.role?'selected':''}>${v}</option>`).join('')}</select></label><label class="full">Verification code<input name="code" inputmode="numeric" pattern="123456" required placeholder="Enter 123456"><small>Verification email delivery is not yet connected.</small></label></div><button class="btn">${kind==='signup'?'Continue to full registration':'Open account'}</button><p class="muted">${kind==='signup'?'Already tried signup?':'New to Talind?'} <button class="text-button" type="button" onclick="authScreen('${kind==='signup'?'login':'signup'}')">${kind==='signup'?'Log in':'Sign up'}</button></p><p id="auth-error" class="form-error" role="alert"></p></form>`);$('#auth-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target),email=d.get('email').trim().toLowerCase(),role=d.get('role'),key=email+'|'+role;if(d.get('code')!=='123456')return;if(kind==='login'&&!registration.accounts.has(key)){$('#auth-error').textContent='No account for this email and category is available in this browser session.';return}if(kind==='signup'&&registration.accounts.has(key)){$('#auth-error').textContent='This session account already exists. Use Log in.';return}if(kind==='signup'){registration.accounts.set(key,{fields:{email},skills:[],evidence:[],links:[],complete:false})}registration.records[role]=registration.accounts.get(key);registration.active={key,email,role};state.role=role;$('#role').value=role;registration.step=0;$('#modal').close();updateAuthHeader();navigate('profile');toast(kind==='signup'?'Complete your profile to finish registration.':'Account opened for this session.')}}
function updateAuthHeader(){let h=$('#auth-actions');h.innerHTML=`<button class="btn light" onclick="navigate('profile')">Create / edit profile</button>`}
function demoLogout(){registration.active=null;Object.keys(registration.records).forEach(k=>delete registration.records[k]);updateAuthHeader();navigate('explore');toast('Session signed out.')}
const originalChangeRole=changeRole;changeRole=function(r){registration.step=0;originalChangeRole(r)};
const actions=document.createElement('div');actions.id='auth-actions';actions.className='auth-actions';$('header').insertBefore(actions,$('.avatar-btn'));updateAuthHeader();if(location.hash==='#profile')render();
// Keep required-field checks effective even when users jump directly to Review.
const originalMissingFields=missingFields;
missingFields=function(){const m=originalMissingFields(),f=record().fields;for(const q of [...common,...questions[state.role].background,...questions[state.role].preferences]){const v=String(f[q.key]??'').trim();if(!v)continue;if(q.type==='email'&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v))m.push('Valid '+q.label);if(q.type==='number'&&(!Number.isFinite(Number(v))||Number(v)<0||!Number.isInteger(Number(v))))m.push('Valid non-negative whole number: '+q.label);if(q.type==='url'){try{if(!['http:','https:'].includes(new URL(v).protocol))throw Error()}catch{m.push('Valid website URL')}}if(q.type==='select'&&!q.options.includes(v))m.push('Valid choice: '+q.label)}if(state.role==='learner'&&f.accountFor==='Adult learner (18+)'&&f.ageBand!=='18+')m.push('Use a parent / guardian account for a learner under 18');return m};
const originalStepFields=stepFields;stepFields=function(n){const arr=originalStepFields(n);return n===1||n===3?[...arr,field(n===1?'backgroundOther':'preferencesOther','If you selected Other, or need to add context, explain here','textarea')]:arr};
const originalWorkspace=workspace;workspace=function(){originalWorkspace();const r=record();$('#main').insertAdjacentHTML('afterbegin',`<div class="notice profile-prompt"><strong>${r.complete?'Your profile is complete.':'Complete your skills-first profile.'}</strong> ${r.skills.length} skills · ${r.evidence.length+r.links.length} evidence items <a class="btn light" href="#profile">${r.complete?'Review profile':'Continue registration'} →</a></div>`)};
function openEvidence(){registration.step=4;navigate('profile')}
const workspaceWithRegistration=workspace;workspace=function(){workspaceWithRegistration();if(state.role==='teacher')$('#main').insertAdjacentHTML('afterbegin','<div class="workspace-links" style="margin-bottom:16px"><button class="btn outline" onclick="openEvidence()">Résumé, certificates & video evidence ↗</button></div>')};
